        INSERT INTO topics (semester_id, title, slug, "order", usmle_step)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'The notochord primarily induces formation of the:', '["Neural crest", "Neural plate", "Placenta", "Somites", "Cloacal membrane"]', 1, 'The notochord induces the overlying ectoderm to become the neural plate.'),
    (v_topic_id, 'Failure of closure of the cranial neuropore can result in:', '["Spina bifida occulta", "Anencephaly", "Meckel diverticulum", "Omphalocele", "Cleft lip"]', 1, 'Incomplete closure of the cranial neuropore leads to major brain defects like anencephaly.'),
    (v_topic_id, 'Failure of closure of the caudal neuropore is associated with:', '["Anencephaly", "Spina bifida", "Tracheoesophageal fistula", "Renal agenesis", "Tetralogy of Fallot"]', 1, 'Caudal neuropore failure leads to various forms of spina bifida.'),
    (v_topic_id, 'Maternal folate deficiency is strongly associated with:', '["Duodenal atresia", "Neural tube defects", "Pyloric stenosis", "Choanal atresia", "Annular pancreas"]', 1, 'Folic acid is essential for proper neural tube closure.'),
    (v_topic_id, 'Neural crest cells arise from:', '["Endoderm", "Mesoderm", "Neuroectoderm at the edge of the neural folds", "Surface ectoderm only", "Extraembryonic mesoderm"]', 2, 'Neural crest cells originate from the neural fold margins.'),
    (v_topic_id, 'Which of the following is a neural crest derivative?', '["Hepatocyte", "Adrenal medulla", "Nephron epithelium", "Skeletal muscle", "Endocardium"]', 1, 'Adrenal medulla (chromaffin cells) is a major neural crest derivative.'),
    (v_topic_id, 'Vertebrae develop primarily from the:', '["Dermatome", "Sclerotome", "Myotome", "Neural crest", "Lateral plate mesoderm"]', 1, 'The sclerotome part of the somite gives rise to the vertebrae and ribs.'),
    (v_topic_id, 'Skeletal muscles of the trunk arise mainly from the:', '["Dermatome", "Myotome", "Sclerotome", "Endoderm", "Intermediate mesoderm"]', 1, 'The myotome part of the somite gives rise to skeletal muscle.'),
    (v_topic_id, 'Dermis of the back arises mainly from the:', '["Dermatome", "Sclerotome", "Neural crest", "Endoderm", "Somatic lateral plate mesoderm"]', 0, 'The dermatome part of the somite provides the dermis of the back.'),
    (v_topic_id, 'Pharyngeal pouches are lined by:', '["Surface ectoderm", "Endoderm", "Neural crest", "Intermediate mesoderm", "Somatic mesoderm"]', 1, 'Pharyngeal pouches are internal and lined by foregut endoderm.'),
    (v_topic_id, 'Persistence of the cervical sinus is associated with anomalies of the:', '["First pharyngeal cleft", "Second pharyngeal cleft", "Third pouch", "Thyroglossal duct", "Allantois"]', 1, 'Failure of the 2nd pharyngeal cleft to obliterate leaves a cervical sinus.'),
    (v_topic_id, 'The first pharyngeal arch is associated with which cranial nerve?', '["CN VII", "CN V", "CN IX", "CN X", "CN XII"]', 1, 'CN V (Trigeminal) is the nerve of the 1st arch.'),
    (v_topic_id, 'Muscles of mastication are derivatives of the:', '["First arch", "Second arch", "Third arch", "Fourth arch", "Sixth arch"]', 0, 'The 1st arch muscles include the muscles of mastication.'),
    (v_topic_id, 'The facial nerve is associated with the:', '["First arch", "Second arch", "Third arch", "Fourth arch", "Sixth arch"]', 1, 'CN VII (Facial) is the nerve of the 2nd arch.'),
    (v_topic_id, 'Stylopharyngeus is a derivative of the:', '["First arch", "Second arch", "Third arch", "Fourth arch", "Sixth arch"]', 2, 'The 3rd arch nerve is CN IX, which supplies the stylopharyngeus.'),
    (v_topic_id, 'The third aortic arch contributes to the:', '["Pulmonary arteries", "Common carotid arteries", "Ductus arteriosus", "Coronary arteries", "Umbilical arteries"]', 1, 'The 3rd aortic arch forms the common and internal carotid stems.'),
    (v_topic_id, 'The left fourth aortic arch contributes to the:', '["Right subclavian artery only", "Arch of the aorta", "Pulmonary trunk", "Ductus venosus", "Vitelline artery"]', 1, 'The left 4th arch forms part of the aortic arch.'),
    (v_topic_id, 'The left sixth aortic arch contributes to the:', '["Common carotid artery", "Ductus arteriosus", "Arch of the aorta", "Subclavian artery", "Coronary sinus"]', 1, 'The left 6th arch contributes to the pulmonary artery and ductus arteriosus.'),
    (v_topic_id, 'The primitive heart forms initially from:', '["One endodermal tube", "Two endocardial tubes that fuse", "Neural crest cells only", "A hindgut diverticulum", "Somites only"]', 1, 'Horizontal folding brings the pair of endocardial tubes together for fusion.'),
    (v_topic_id, 'Normal looping of the heart tube occurs toward the:', '["Left", "Right", "Cranial direction only", "Dorsal side only", "Caudal side only"]', 1, 'Looping occurs to the right (D-looping).'),
    (v_topic_id, 'The septum primum forms part of the:', '["Ventricular septum", "Interatrial septum", "Tracheoesophageal septum", "Aorticopulmonary septum", "Pleuroperitoneal membrane"]', 1, 'The septum primum is the first phase of atrial septation.'),
    (v_topic_id, 'Before birth, the foramen ovale allows blood flow from:', '["Left atrium to right atrium", "Right atrium to left atrium", "Right ventricle to left ventricle", "Pulmonary artery to aorta", "Umbilical vein to portal vein"]', 1, 'Prenatally, blood shunts from R to L atrium through the foramen.'),
    (v_topic_id, 'Neural crest contributes importantly to partitioning of the:', '["Primitive atrium", "Truncus arteriosus", "Hepatic diverticulum", "Cloaca", "Yolk sac"]', 1, 'Neural crest forms the spiral aorticopulmonary septum in the truncus arteriosus.'),
    (v_topic_id, 'The membranous part of the interventricular septum develops largely from:', '["Somites", "Endocardial cushions", "Surface ectoderm", "Vitelline veins", "Pleuropericardial folds"]', 1, 'Failure of the cushions to contribute properly often leads to membranous VSDs.'),
    (v_topic_id, 'Tracheoesophageal fistula results from abnormal partitioning of the:', '["Midgut", "Foregut", "Hindgut", "Cloaca", "Allantois"]', 1, 'Failure of the tracheoesophageal septum to separate the primitive foregut correctly.'),
    (v_topic_id, 'The trachea and esophagus are separated by the:', '["Septum transversum", "Tracheoesophageal septum", "Aorticopulmonary septum", "Urorectal septum", "Pleuroperitoneal membrane"]', 1, 'Correct partitioning requires the TE septum.'),
    (v_topic_id, 'The midgut normally rotates:', '["90° clockwise", "180° clockwise", "270° counterclockwise", "360° clockwise", "180° counterclockwise"]', 2, 'The 270° CCW rotation around the SMA is essential for normal anatomy.'),
    (v_topic_id, 'Meckel diverticulum results from persistence of the:', '["Urachus", "Vitelline duct", "Allantois", "Mesonephric duct", "Paramesonephric duct"]', 1, 'Meckel’s is a remnant of the vitelline (yolk) duct.'),
    (v_topic_id, 'Meckel diverticulum is classically located on the:', '["Mesenteric border of jejunum", "Anti-mesenteric border of ileum", "Colon", "Greater curvature of stomach", "Duodenum near ampulla"]', 1, 'It occurs on the anti-mesenteric border, usually 2 feet from the ileocecal valve.'),
    (v_topic_id, 'The urorectal septum divides the:', '["Foregut", "Cloaca", "Midgut", "Neural tube", "Coelom"]', 1, 'The septum divides the cloaca into the urogenital and rectal portions.'),
    (v_topic_id, 'The lower anal canal develops from the:', '["Hindgut endoderm", "Proctodeal ectoderm", "Neural crest", "Mesonephric duct", "Allantois"]', 1, 'The proctodeum (ectoderm) forms the distal part of the anal canal.'),
    (v_topic_id, 'The liver develops from the:', '["Midgut loop", "Hepatic diverticulum from foregut endoderm", "Neural crest", "Septum transversum only", "Mesonephric ridge"]', 1, 'The liver bud grows from the endodermal floor of the foregut.'),
    (v_topic_id, 'The ventral pancreatic bud forms the:', '["Body and tail of pancreas", "Uncinate process and inferior head", "Entire pancreas", "Spleen", "Gallbladder"]', 1, 'The ventral bud contributes to the inferior head and uncinate process.'),
    (v_topic_id, 'Annular pancreas is due to abnormal:', '["Fusion of pleuroperitoneal membranes", "Rotation of the ventral pancreatic bud", "Midgut rotation", "Neural tube closure", "Cloacal septation"]', 1, 'A bifid ventral bud encircling the duodenum during rotation.'),
    (v_topic_id, 'The epithelium of the respiratory tract is derived from:', '["Endoderm", "Neural crest", "Somatic mesoderm", "Surface ectoderm", "Intermediate mesoderm"]', 0, 'Internal linings are derived from endoderm outpocketing.'),
    (v_topic_id, 'Surfactant is produced by:', '["Type I pneumocytes", "Type II pneumocytes", "Alveolar macrophages", "Clara cells only", "Ciliated columnar cells"]', 1, 'Type II pneumocytes produce surfactant in the late stages of lung maturation.'),
    (v_topic_id, 'The most common congenital diaphragmatic hernia is due to failure of closure of the:', '["Esophageal hiatus", "Pleuroperitoneal canal", "Foramen cecum", "Umbilical ring", "Aortic hiatus"]', 1, 'Left-sided Bochdalek hernia involves the pleuroperitoneal canal.'),
    (v_topic_id, 'A major embryologic component of the diaphragm is the:', '["Septum transversum", "Neural crest", "Notochord", "Yolk sac", "Mesonephric duct"]', 0, 'The septum transversum contributes much of the central tendon.'),
    (v_topic_id, 'The definitive kidney is the:', '["Pronephros", "Mesonephros", "Metanephros", "Paramesonephros", "Cloaca"]', 2, 'Definitive kidney = Metanephros.'),
    (v_topic_id, 'The ureteric bud arises from the:', '["Paramesonephric duct", "Mesonephric duct", "Allantois", "Hindgut", "Urogenital sinus"]', 1, 'The ureteric bud sprouts from the mesonephric duct near the cloaca.'),
    (v_topic_id, 'Nephrons are derived from the:', '["Ureteric bud", "Metanephric mesenchyme", "Mesonephric duct", "Neural crest", "Surface ectoderm"]', 1, 'Inductive interaction between the bud and mesenchyme leads to nephron formation.'),
    (v_topic_id, 'The urinary bladder develops mainly from the:', '["Urogenital sinus", "Foregut", "Midgut", "Neural tube", "Vitelline duct"]', 0, 'Most of the bladder epithelial lining comes from the UG sinus.'),
    (v_topic_id, 'The urachus is a remnant of the:', '["Vitelline duct", "Allantois", "Mesonephric duct", "Müllerian duct", "Ductus venosus"]', 1, 'The stalks of the allantois becomes the urachus.'),
    (v_topic_id, 'Testis determination in an XY embryo is initiated by the:', '["SOX2 gene", "SRY gene", "CFTR gene", "PAX6 gene", "HOXA13 gene"]', 1, 'SRY on the Y chromosome acts as the primary switch.'),
    (v_topic_id, 'Sertoli cells secrete:', '["Testosterone", "Anti-Müllerian hormone", "Dihydrotestosterone", "hCG", "FSH"]', 1, 'AMH causes regression of Müllerian ducts in males.'),
    (v_topic_id, 'Leydig cells secrete:', '["Anti-Müllerian hormone", "Testosterone", "Estrogen only", "FSH", "Oxytocin"]', 1, 'Leydig cells are the primary source of fetal testosterone.'),
    (v_topic_id, 'Male internal genital ducts develop from the:', '["Paramesonephric ducts", "Mesonephric ducts", "Ureteric buds", "Allantois", "Vitelline ducts"]', 1, 'Wolffian (mesonephric) ducts become the male ductal system.'),
    (v_topic_id, 'DHT is required mainly for development of the:', '["Wolffian ducts", "External male genitalia and prostate", "Müllerian ducts", "Testis only", "Kidney"]', 1, 'Dihydrotestosterone is needed for external male characteristics.'),
    (v_topic_id, 'The apical ectodermal ridge is essential for:', '["Neural crest migration", "Proximodistal growth of limbs", "Cardiac looping", "Cloacal partitioning", "Foregut separation"]', 1, 'The AER promotes outgrowth of the limb bud.'),
    (v_topic_id, 'The retina develops from:', '["Surface ectoderm", "Neuroectoderm of the optic cup", "Endoderm", "Neural crest only", "Mesoderm only"]', 1, 'The retina is an extension of the neuroectoderm of the brain.'),
    (v_topic_id, 'The lens of the eye develops from:', '["Neuroectoderm", "Surface ectoderm", "Neural crest", "Endoderm", "Intermediate mesoderm"]', 1, 'Induction by the optic vesicle leads surface ectoderm to form the lens.'),
    (v_topic_id, 'The inner ear develops from the:', '["First pharyngeal pouch", "Otic placode", "Optic cup", "Neural crest only", "Second pharyngeal cleft"]', 1, 'Surface ectoderm invaginates as the otic placode.'),
    (v_topic_id, 'The middle ear cavity is derived mainly from the:', '["First pharyngeal cleft", "First pharyngeal pouch", "Second pharyngeal pouch", "Otic vesicle", "Surface ectoderm only"]', 1, 'First pouch forms the tubotympanic recess.'),
    (v_topic_id, 'The external auditory canal develops from the:', '["First pharyngeal pouch", "First pharyngeal cleft", "Second pharyngeal arch", "Otic placode", "Foregut"]', 1, 'The 1st cleft becomes the external auditory meatus.'),
    (v_topic_id, 'The ossicles of the middle ear are primarily derived from:', '["First and second pharyngeal arches", "Second and third pharyngeal arches", "Third and fourth pharyngeal arches", "Neural tube", "Otic placode only"]', 0, 'Ossicles derive from Meckel (1st) and Reichert (2nd) cartilage.'),
    (v_topic_id, 'The thymus develops mainly from the:', '["First pharyngeal pouch", "Second pharyngeal pouch", "Third pharyngeal pouch", "Fourth pharyngeal pouch", "Fifth pharyngeal pouch"]', 2, 'The 3rd pouch contributes most of the thymus.'),
    (v_topic_id, 'The inferior parathyroid glands develop from the:', '["Second pouch", "Third pouch", "Fourth pouch", "First arch", "Thyroglossal duct"]', 1, '3rd pouch forms inferior parathyroids; 4th forms superior parathyroids.'),
    (v_topic_id, 'The superior parathyroid glands develop from the:', '["Second pouch", "Third pouch", "Fourth pouch", "First cleft", "Ultimobranchial body"]', 2, 'The 4th pouch becomes the superior parathyroids.'),
    (v_topic_id, 'Parafollicular C cells of the thyroid are derived from:', '["Thyroglossal duct only", "Ultimobranchial body associated with the fourth/fifth pouch region", "Surface ectoderm", "Sclerotome", "Mesonephric duct"]', 1, 'Neural crest cells migrate into the ultimobranchial body.'),
    (v_topic_id, 'The thyroid gland begins as an endodermal diverticulum from the floor of the primitive:', '["Stomach", "Pharynx", "Trachea", "Foregut-midhgut junction", "Hindgut"]', 1, 'Originates from the foramen cecum on the floor of the pharynx.'),
    (v_topic_id, 'A thyroglossal duct cyst is typically located:', '["Lateral to the sternocleidomastoid", "In the midline near the hyoid bone", "In the posterior triangle of the neck", "In the superior mediastinum", "In the parotid region"]', 1, 'Most commonly found as a midline neck mass.'),
    (v_topic_id, 'A thyroglossal duct cyst characteristically moves with:', '["Respiration only", "Swallowing and protrusion of the tongue", "Blinking", "Shoulder movement", "Jaw opening only"]', 1, 'Specific physical exam finding due to hyoid/tongue attachment.'),
    (v_topic_id, 'The spleen develops from:', '["Foregut endoderm", "Mesoderm in the dorsal mesogastrium", "Neural crest", "Ventral pancreatic bud", "Septum transversum"]', 1, 'Different from most GI organs, it is mesodermal in origin.'),
    (v_topic_id, 'The adrenal cortex is derived from:', '["Neural crest", "Mesoderm", "Endoderm", "Surface ectoderm", "Notochord"]', 1, 'Cortex is mesodermal; medulla is neural crest.'),
    (v_topic_id, 'The adrenal medulla is derived from:', '["Endoderm", "Intermediate mesoderm", "Neural crest", "Surface ectoderm", "Foregut mesenchyme"]', 2, 'Derived from sympathetic neural crest cells.'),
    (v_topic_id, 'The pleural cavities are separated from the peritoneal cavity primarily by formation of the:', '["Pleuroperitoneal membranes", "Endocardial cushions", "Urorectal septum", "Septum primum", "Otic vesicles"]', 0, 'These membranes are crucial for complete partition of the coelom.'),
    (v_topic_id, 'The parietal pleura is derived mainly from:', '["Splanchnic mesoderm", "Somatic mesoderm", "Endoderm", "Neural crest", "Surface ectoderm"]', 1, 'Lining of the body wall comes from somatic (parietal) mesoderm.'),
    (v_topic_id, 'The visceral pleura is derived mainly from:', '["Somatic mesoderm", "Splanchnic mesoderm", "Surface ectoderm", "Neural crest", "Endoderm only"]', 1, 'Lining of the organ surface comes from splanchnic (visceral) mesoderm.'),
    (v_topic_id, 'The serosa covering the gut tube is derived from:', '["Endoderm", "Splanchnic mesoderm", "Somatic mesoderm", "Neural crest", "Ectoderm"]', 1, 'Splanchnic mesoderm provides the outer serosal covering.'),
    (v_topic_id, 'The epithelium of the gastrointestinal tract is derived primarily from:', '["Ectoderm", "Endoderm", "Neural crest", "Somatic mesoderm", "Intermediate mesoderm"]', 1, 'Inner mucosal lining is endoderm.'),
    (v_topic_id, 'Smooth muscle and connective tissue of the gut are derived mainly from:', '["Endoderm", "Splanchnic mesoderm", "Neural crest only", "Surface ectoderm", "Somites only"]', 1, 'Supporting gut layers come from mesoderm.'),
    (v_topic_id, 'Aganglionic megacolon (Hirschsprung disease) results from failure of:', '["Midgut rotation", "Neural crest migration into the bowel wall", "Urorectal septum formation", "Vitelline duct closure", "Pancreatic bud fusion"]', 1, 'Absence of enteric plexus due to lack of crest migration.'),
    (v_topic_id, 'In Hirschsprung disease, the affected bowel segment lacks:', '["Villi", "Enteric ganglion cells", "Smooth muscle", "Peyer patches", "Goblet cells"]', 1, 'Symptoms arise because that segment cannot relax (lack of Auerbach/Meissner plexuses).'),
    (v_topic_id, 'Duodenal atresia commonly results from failure of:', '["Foregut separation", "Recanalization of the intestinal lumen", "Midgut return from herniation", "Neural tube closure", "Cloacal partitioning"]', 1, 'Failure of the gut to hollow out again after a temporary solid phase.'),
    (v_topic_id, '“Double bubble” on neonatal imaging classically suggests:', '["Jejunal atresia", "Duodenal atresia", "Meckel diverticulum", "Hirschsprung disease", "Imperforate anus"]', 1, 'Result of dilated stomach and proximal duodenum.'),
    (v_topic_id, 'Failure of recanalization can also cause:', '["Esophageal atresia", "Intestinal stenosis", "Renal agenesis", "Tetralogy of Fallot", "Dextrocardia"]', 1, 'Partial failure results in stenosis; total failure in atresia.'),
    (v_topic_id, 'Omphalocele is characterized by:', '["Herniation through the umbilicus covered by peritoneum/amniotic membrane", "Lateral abdominal wall defect with no covering membrane", "Failure of cloacal division", "Diaphragmatic rupture after birth", "Ventral pancreatic overgrowth"]', 0, 'Protrusion of viscera through the umbilical ring.'),
    (v_topic_id, 'Gastroschisis differs from omphalocele because gastroschisis:', '["Is covered by amnion", "Is usually a midline defect through the umbilical ring", "Typically occurs lateral to the umbilicus and lacks a covering sac", "Is caused by persistent physiologic herniation only", "Is strongly linked to trisomy 21 in all cases"]', 2, 'Gastroschisis usually has naked bowel to the right of the umbilicus.'),
    (v_topic_id, 'The dorsal mesentery persists in much of the gut and contributes to structures such as the:', '["Lesser omentum only", "Greater omentum and mesenteries", "Falciform ligament only", "Coronary ligament of liver only", "Diaphragm only"]', 1, 'Mesenteries support the intestinal loops.'),
    (v_topic_id, 'The ventral mesentery gives rise primarily to the:', '["Greater omentum and gastrosplenic ligament", "Lesser omentum and falciform ligament", "Mesentery of jejunum", "Mesoappendix only", "Sigmoid mesocolon only"]', 1, 'Remains mainly near the liver/stomach region.'),
    (v_topic_id, 'The appendix develops from the:', '["Foregut", "Cecal diverticulum of the midgut", "Hindgut cloaca", "Dorsal pancreatic bud", "Vitelline duct remnant"]', 1, 'The appendix is a midgut derivative.'),
    (v_topic_id, 'The upper one-third of the anal canal is derived from:', '["Proctodeal ectoderm", "Hindgut endoderm", "Neural crest", "Mesonephric duct", "Allantois"]', 1, 'Endodermal origin above the pectinate line.'),
    (v_topic_id, 'The pectinate line marks the junction between:', '["Foregut and midgut", "Endodermal hindgut and ectodermal proctodeum", "Midgut and hindgut", "Mesonephric and paramesonephric ducts", "Somatic and splanchnic mesoderm"]', 1, 'Crucial landmark for clinical and developmental differences.'),
    (v_topic_id, 'The ureter, renal pelvis, major calyces, and minor calyces arise from the:', '["Metanephric mesenchyme", "Ureteric bud", "Pronephric duct", "Allantois", "Cloacal membrane"]', 1, 'All from the branching ureteric bud.'),
    (v_topic_id, 'Failure of one ureteric bud to form can lead to:', '["Polycystic ovary syndrome", "Renal agenesis", "Omphalocele", "Cleft lip", "Annular pancreas"]', 1, 'No bud means no collecting system and no inductive stimulus for nephrons.'),
    (v_topic_id, 'Horseshoe kidney occurs when the kidneys:', '["Fail to ascend from the pelvis", "Fuse at their lower poles and get trapped under the inferior mesenteric artery", "Develop from the mesonephros only", "Become duplicated completely", "Fail to form nephrons"]', 1, 'Fusion prevents full ascent.'),
    (v_topic_id, 'During ascent, the kidneys normally move from the:', '["Thorax to abdomen", "Pelvis to upper abdomen", "Neck to thorax", "Midgut to retroperitoneum", "Retroperitoneum to pelvis"]', 1, 'Move from S1 level to T12-L3 region.'),
    (v_topic_id, 'In females, the uterus and upper vagina develop from the:', '["Mesonephric ducts", "Paramesonephric ducts", "Ureteric buds", "Allantois", "Proctodeum"]', 1, 'Paramesonephric (Müllerian) ducts fuse to form these organs.'),
    (v_topic_id, 'Failure of fusion of the paramesonephric ducts may lead to a:', '["Bicornuate uterus", "Hypospadias", "Cryptorchid testis", "Ectopic ureter", "Imperforate hymen"]', 0, 'Partial fusion leads to variant uterine shapes.'),
    (v_topic_id, 'The lower portion of the vagina develops mainly from the:', '["Mesonephric duct", "Urogenital sinus", "Hindgut", "Neural crest", "Surface ectoderm only"]', 1, 'Dual origin: upper Müllerian, lower sinovaginal bulbs (from UG sinus).'),
    (v_topic_id, 'Testicular descent is influenced importantly by:', '["Estrogen only", "Androgens and gubernaculum guidance", "Prolactin only", "Thyroxine only", "Neural crest migration only"]', 1, 'Testosterone and the gubernaculum pull/guide the testis into the scrotum.'),
    (v_topic_id, 'Failure of testicular descent is termed:', '["Epispadias", "Cryptorchidism", "Hypospadias", "Chordee", "Phimosis"]', 1, 'Risk factor for infertility and cancer.'),
    (v_topic_id, 'Hypospadias results from failure of fusion of the:', '["Labioscrotal swellings", "Urethral folds", "Genital tubercle", "Mesonephric ducts", "Paramesonephric ducts"]', 1, 'Abnormal opening on the ventral surface of the penis.'),
    (v_topic_id, 'The penis or clitoris develops from the:', '["Urethral folds", "Genital tubercle", "Labioscrotal swellings", "Müllerian ducts", "Mesonephric ducts"]', 1, 'Primitive structure that differentiates based on DHT.'),
    (v_topic_id, 'The scrotum in males and labia majora in females are derived from the:', '["Urethral folds", "Genital tubercle", "Labioscrotal swellings", "Cloacal membrane", "Mesonephric ducts"]', 2, 'Homologous structures from the swellings.'),
    (v_topic_id, 'The upper limb buds appear slightly before lower limb buds during:', '["Week 2", "Week 4", "Week 8", "Week 12", "Week 20"]', 1, 'Late 4th week onset.'),
    (v_topic_id, 'Polydactyly most often reflects abnormal patterning involving the:', '["Apical ectodermal ridge only", "Zone of polarizing activity", "Notochord", "Neural tube floor plate", "Pleuroperitoneal membrane"]', 1, 'ZPA (Zone of Polarizing Activity) coordinates anterior-posterior patterning.'),
    (v_topic_id, 'Syndactyly usually results from failure of:', '["Limb bud initiation", "Apoptosis between digital rays", "Somite formation", "Myotome migration", "Neural crest induction"]', 1, 'Digital rays must be separated by programmed cell death.'),
    (v_topic_id, 'The corneal stroma and endothelium are derived mainly from:', '["Endoderm", "Neural crest", "Surface ectoderm", "Intermediate mesoderm", "Sclerotome"]', 1, 'Eye connective tissues have significant crest contribution.'),
    (v_topic_id, 'The optic nerve develops as an outgrowth of the:', '["Surface ectoderm", "Neuroectoderm", "Endoderm", "Neural crest only", "Mesoderm only"]', 1, 'The optic stalk is neuroectodermal.');
