-- ==========================================
-- Topic: Systemic Embryology - 100 Standalone MCQs
-- Semester 2 First Year
-- ==========================================

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- 1. Get or Create Topic ID
    SELECT id INTO v_topic_id FROM topics WHERE title = 'Systemic Embryology' AND semester_id = 2;
    
    IF v_topic_id IS NULL THEN
        VALUES (2, 'Systemic Embryology', 'systemic-embryology', 10, 1)
        RETURNING id INTO v_topic_id;
    END IF;

    -- 2. Cleanup existing standalone MCQs for this topic
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- 3. Insert 100 MCQs

    RAISE NOTICE 'Systemic Embryology MCQs Migration Completed (100 Questions).';
END $$;
